<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Document;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class DocumentController extends Controller{public function index(){return view('admin.documents.index',['items'=>Document::orderBy('category')->orderBy('sort')->paginate(40)]);}public function create(){return view('admin.documents.form',['item'=>new Document]);}public function store(Request $r){Document::create($this->data($r));return redirect()->route('admin.documents.index')->with('ok','Документ добавлен');}public function edit(Document $document){return view('admin.documents.form',['item'=>$document]);}public function update(Request $r,Document $document){$old=$document->file;$data=$this->data($r,$document);$document->update($data);if(isset($data['file'])&&$old&&$old!==$data['file'])Storage::disk('public')->delete($old);return redirect()->route('admin.documents.index')->with('ok','Сохранено');}public function destroy(Document $document){if($document->file)Storage::disk('public')->delete($document->file);$document->delete();return back();}private function data(Request $r,?Document $item=null){$rules=['title'=>'required|max:255','description'=>'nullable|max:1000','number'=>'nullable|max:100','document_date'=>'nullable|date','category'=>'required|max:255','published_at'=>'nullable|date','sort'=>'nullable|integer','file'=>($item?'nullable':'required').'|file|max:20480|mimes:pdf,doc,docx,xls,xlsx'];$d=$r->validate($rules);if($r->hasFile('file'))$d['file']=$r->file('file')->store('documents','public');else unset($d['file']);$d['is_published']=$r->boolean('is_published');return $d;}}